package com.hospital.mes.reporting;
import com.hospital.mes.reporting.application.*;
import com.hospital.mes.audit.application.*;
import com.hospital.mes.common.exception.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Test-owned real WMS records, real source persistence and authorization, transaction rollback inherited. */
class PrintDataSourceIT extends PrintTypeBatchIT {
 @Autowired PrintDataSourceService sourceService;
 private com.fasterxml.jackson.databind.JsonNode current;
 @BeforeEach void sourceSetup(){rights.addAll(Set.of("print:source:view","print:source:manage","print:source:publish"));as(1);current=sourceService.detail(sourceService.fixed(1,"WMS_RECEIPT",null).source().getId().toString());}
 @Test void savedDraftReopensAndOldExplicitPublicationDoesNotPublishNewDraft(){String id=current.path("id").asText();var config=(ObjectNode)current.path("published").path("configuration").deepCopy();config.put("sourceName","新的真实草稿");var request=json.createObjectNode().put("expectedVersion",current.path("versionNo").asLong()).put("sourceName","新的真实草稿").put("reason","测试保存重开");request.putArray("businessTypes").add("WMS_RECEIPT");request.set("configuration",config);var draft=sourceService.save(id,request,current.path("versionNo").asText(),key());assertThat(sourceService.detail(id).path("draft").path("configuration")).isEqualTo(draft.path("draft").path("configuration"));assertThat(draft.path("published").path("configHash")).isEqualTo(current.path("published").path("configHash"));assertThat(draft.path("draft").path("id")).isNotEqualTo(current.path("published").path("id"));}
 @Test void existingTypeBindingIsDisabledAndServerRejectsAnotherSource(){String id=current.path("id").asText();var choices=sourceService.documentTypes(null);assertThat(choices.findValues("disabled").stream().anyMatch(v->v.asBoolean())).isTrue();var create=json.createObjectNode().put("sourceCode","CONFLICT"+suffix).put("sourceName",current.path("sourceName").asText()).put("reason","验证唯一类型冲突");create.putArray("businessTypes").add("WMS_RECEIPT");create.set("configuration",current.path("published").path("configuration"));assertThatThrownBy(()->sourceService.save(null,create,null,key())).isInstanceOf(ResourceConflictException.class).hasMessageContaining("已绑定");}
 @Test void currentBusinessReadRevocationBlocksResolution(){var fixed=sourceService.fixed(1,"WMS_RECEIPT",null);rights.remove("wms:receipt:view");as(1);assertThatThrownBy(()->sourceService.resolve(fixed,first,false)).isInstanceOf(PermissionException.class);}
 @Test void metadataChangeExpiresSavedDraftValidation(){String id=current.path("id").asText();var config=current.path("published").path("configuration");var draftReq=json.createObjectNode().put("expectedVersion",current.path("versionNo").asLong()).put("sourceName",current.path("sourceName").asText()).put("reason","校验过期测试");draftReq.putArray("businessTypes").add("WMS_RECEIPT");draftReq.set("configuration",config);var draft=sourceService.save(id,draftReq,current.path("versionNo").asText(),key());var validate=json.createObjectNode().put("expectedVersion",draft.path("versionNo").asLong()).put("reason","真实样本");validate.putArray("samples").addObject().put("businessType","WMS_RECEIPT").put("recordId",first);var proof=sourceService.validate(id,validate,draft.path("versionNo").asText(),key());var meta=sourceService.getMetadata("WMS_RECEIPT");var update=json.createObjectNode().put("expectedVersion",meta.path("versionNo").asLong()).put("authorizationPolicyRef",meta.path("authorizationPolicyRef").asText()).put("reason","元数据版本更新");update.set("compatibleMainCatalogIds",meta.path("compatibleMainCatalogIds"));update.set("fixedTypeFilters",meta.path("fixedTypeFilters"));sourceService.putMetadata("WMS_RECEIPT",update,meta.path("versionNo").asText(),key());var publish=json.createObjectNode().put("expectedVersion",draft.path("versionNo").asLong()).put("revisionId",draft.path("draft").path("id").asText()).put("configHash",draft.path("draft").path("configHash").asText()).put("validationId",proof.path("id").asText()).put("reason","拒绝过期发布");assertThatThrownBy(()->sourceService.publish(id,publish,draft.path("versionNo").asText(),key())).isInstanceOf(ComplianceException.class).hasMessageContaining("失效");}
}
